import { Group, Object3D, Mesh, Vector3, Euler } from 'three/webgpu';
import { gsap } from 'gsap';
import { disposeObject } from '@/primitives';

/**
 * @typedef {Object} NodeConfig
 * @property {Object} position
 * @property {Object} rotation
 * @property {Object} scale
 * @property {Array<{name:string, params:any}>} cinematicPrimitives
 * @property {Array<{event:string, effect:string}>} interactions
 * @property {string} meshUrl
 */

/**
 * @typedef {Object} NodeContext
 * @property {(url:string)=>any} glbLoader
 * @property {{[key:string]:(obj:Object3D,params:any)=>void}} primitives
 * @property {(event:string)=>void} [emit]
 */

/**
 * Create the Journal badge node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  // root container
  const root = new Group();
  root.name = 'hub-journal-badge';
  root.position.set(
    config.position?.x ?? 0,
    config.position?.y ?? 0,
    config.position?.z ?? 0
  );
  root.rotation.set(
    (config.rotation?.x ?? 0) * (Math.PI / 180),
    (config.rotation?.y ?? 0) * (Math.PI / 180),
    (config.rotation?.z ?? 0) * (Math.PI / 180)
  );
  root.scale.set(
    config.scale?.x ?? 1,
    config.scale?.y ?? 1,
    config.scale?.z ?? 1
  );

  // Load GLB (synchronous according to specification)
  const gltf = ctx.glbLoader(config.meshUrl);
  const meshRoot = gltf.scene || gltf;

  // Clone the loaded scene to avoid mutating the cached instance
  const badgeMesh = meshRoot.clone(true);
  root.add(badgeMesh);

  // Apply cinematic primitives
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (typeof fn === 'function') {
        fn(root, prim.params);
      }
    }
  }

  // Interaction handling
  const timelines = {};

  const handlers = {};

  // Hover: rise-in (subtle, 0.15 scene units)
  handlers.hover = (event) => {
    // event may be { type: 'enter'|'leave' }
    const direction = event?.type === 'enter' ? 1 : -1;
    if (timelines.hover) timelines.hover.kill();
    timelines.hover = gsap.to(root.position, {
      y: root.position.y + direction * 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
  };

  // Click: emit selection event
  handlers.click = () => {
    if (typeof ctx.emit === 'function') {
      ctx.emit('hub-journal.select');
    }
  };

  root.userData.handlers = handlers;

  // Cleanup
  root.userData.cleanup = () => {
    // Dispose GLTF resources
    root.traverse((obj) => {
      if (obj.isMesh) {
        const mesh = /** @type {Mesh} */ (obj);
        if (mesh.geometry) mesh.geometry.dispose();
        if (mesh.material) {
          if (Array.isArray(mesh.material)) {
            mesh.material.forEach((m) => m.dispose());
          } else {
            mesh.material.dispose();
          }
        }
      }
    });

    // Kill GSAP timelines
    for (const key in timelines) {
      if (timelines[key]) timelines[key].kill();
    }

    // Remove primitives if they expose a dispose (optional)
    if (typeof disposeObject === 'function') {
      disposeObject(root);
    }
  };

  return root;
}
